        <rect x={r - r * 0.55} y={r - r * 0.55} width={r * 1.1} height={r * 1.1} fill={color} transform={`rotate(45 ${r} ${r})`} />
      ) : (
        <circle cx={r} cy={r} r={r * 0.35} fill={color} />
      )}
    </svg>
  )
}

function Row({ glyph, channel, children }: { glyph: React.ReactNode; channel: string; children: React.ReactNode }) {
  return (
    <div className="grid grid-cols-[3rem_1fr] items-center gap-x-3 py-1">
      <div className="flex items-center gap-1">{glyph}</div>
      <p className="text-xs leading-snug">
        <span className="font-medium">{channel}</span> <span className="text-muted-foreground">· {children}</span>
      </p>
    </div>
  )
}

function Section({ title, aside, children }: { title: string; aside?: React.ReactNode; children: React.ReactNode }) {
  return (
    <section className="px-4 py-3">
      <div className="mb-1.5 flex items-baseline justify-between gap-2">
        <h3 className="text-[11px] font-medium uppercase text-muted-foreground">{title}</h3>
        {aside}
      </div>
      {children}
    </section>
  )
}

export function DrkgLegend({
  scene,
  hidden,
  onToggleCluster,
  activeLane,
  phase,
}: {
  scene: Scene
  hidden: Set<number>
  onToggleCluster: (id: number) => void
  activeLane: number | null
  phase: string | null
}) {
  const clusters = scene.clusters ?? []
  const degree = scene.meta.degree
  const named = new Set(['Compound', 'Gene', 'Disease'])
  const typeCount = (name: string) => scene.types.find((t) => t.name === name)?.count ?? 0
  const otherCount = scene.types.filter((t) => !named.has(t.name)).reduce((s, t) => s + t.count, 0)
  const sizeFor = (d: number) => (degree ? 4 + 8 * (Math.log1p(d) / Math.log1p(degree.p99)) : 6)

  return (
    <aside className="flex w-[280px] flex-col overflow-hidden rounded-xl bg-card text-card-foreground ring-1 ring-border backdrop-blur-md">
      <div className="px-4 pt-3 pb-2" aria-live="polite">
        <p className="eyebrow">DRKG · TransE 400-d</p>
        <p className="mt-1.5 truncate text-sm font-medium tabular-nums">{phase ?? 'Ready'}</p>
      </div>
      <Separator />

      <Section title="Profiles">
        <ul className="space-y-0.5">
          {scene.profiles.map((p) => {
            const active = activeLane === p.lane
            return (
              <li key={p.lane} className={cn('flex items-center gap-2 text-xs', active ? 'font-semibold' : 'text-muted-foreground')}>
                <span className="size-2.5 shrink-0 rounded-full" style={{ background: LANE_COLORS[p.lane] }} aria-hidden />
                <span className="truncate">{p.name}</span>
                {active ? <span className="ml-auto text-[10px] font-medium uppercase">● now</span> : null}
              </li>
            )
          })}
        </ul>
      </Section>
      <Separator />

      <Section title="How to read it">
        <Row
          channel="Position"
          glyph={
            <svg width="28" height="14" viewBox="0 0 28 14" aria-hidden>
              <circle cx="5" cy="9" r="2" fill={INK} opacity=".5" />
              <circle cx="11" cy="5" r="2" fill={INK} opacity=".5" />
              <circle cx="22" cy="10" r="2" fill={INK} opacity=".5" />
            </svg>
          }
        >
          embedding layout{scene.meta.projection ? ` (${scene.meta.projection})` : ''}
        </Row>
        <Row
          channel="Colour"
          glyph={[0, 1, 2].map((i) => <span key={i} className="size-2.5 rounded-full" style={{ background: clusterColor(i, clusters[i]) }} />)}
        >
          cluster
        </Row>
        <Row channel="Shape" glyph={['Compound', 'Gene', 'Disease'].map((t) => <TypeGlyph key={t} type={t} size={11} />)}>
          entity type
        </Row>
        <Row
          channel="Size"
          glyph={[1, 2, 3].map((i) => <span key={i} className="rounded-full bg-foreground/50" style={{ width: 2 + i * 2.5, height: 2 + i * 2.5 }} />)}
        >
          graph degree, log
        </Row>
        <Row
          channel="Brightness"
          glyph={[0.2, 0.55, 1].map((o) => <span key={o} className="size-2.5 rounded-full bg-foreground" style={{ opacity: o }} />)}
        >
          closeness to the active query
        </Row>

        <dl className="mt-2 grid grid-cols-[auto_1fr_auto] items-center gap-x-2 gap-y-1 text-xs">
          {(['Compound', 'Gene', 'Disease'] as const).map((t) => (
            <div key={t} className="contents">
              <dt><TypeGlyph type={t} /></dt>
              <dd>{t === 'Compound' ? 'Compound' : t === 'Gene' ? 'Gene' : 'Disease'}</dd>
              <dd className="text-right text-muted-foreground tabular-nums">{fmt(typeCount(t))}</dd>
            </div>
          ))}
          <dt><TypeGlyph type="other" /></dt>
          <dd>Other (pathways, side effects…)</dd>
          <dd className="text-right text-muted-foreground tabular-nums">{fmt(otherCount)}</dd>
        </dl>

        {degree ? (
          <div className="mt-2.5 flex items-end justify-between gap-2 text-[11px] text-muted-foreground tabular-nums">
            {([['min', degree.min], ['median', degree.median], ['p99', degree.p99]] as const).map(([k, d]) => (
              <div key={k} className="flex flex-col items-center gap-1">
                <span className="rounded-full bg-foreground/50" style={{ width: sizeFor(d), height: sizeFor(d) }} aria-hidden />
                <span>{k} {fmt(d)}</span>
              </div>
            ))}
          </div>
        ) : null}
      </Section>

      {clusters.length ? (
        <>
          <Separator />
          <Section
            title={`Clusters · ${clusters.length}`}
            aside={
              hidden.size ? (
                <button
                  type="button"
                  className="text-[11px] font-medium underline-offset-2 hover:underline"
                  onClick={() => clusters.forEach((c) => hidden.has(c.id) && onToggleCluster(c.id))}
                >
                  Show all
                </button>
              ) : null
            }
          >
            <ScrollArea className="-mx-2 h-44">
              <ul className="px-2">
                {clusters.map((c) => {
                  const off = hidden.has(c.id)
                  const Icon = off ? EyeOff : Eye
                  return (
                    <li key={c.id}>
                      <button
                        type="button"
                        aria-pressed={!off}
                        onClick={() => onToggleCluster(c.id)}
                        className="flex w-full items-center gap-2 rounded-md px-1.5 py-1 text-left text-xs hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
                      >
                        <span className={cn('size-2.5 shrink-0 rounded-full', off && 'opacity-30')} style={{ background: clusterColor(c.id, c) }} aria-hidden />
                        <span className={cn('min-w-0 flex-1 truncate', off && 'text-muted-foreground line-through')} title={c.label}>
                          {c.label}
                        </span>
                        <span className="text-muted-foreground tabular-nums">{fmt(c.size)}</span>
                        <Icon className="size-3.5 shrink-0 text-muted-foreground" aria-label={off ? 'Hidden' : 'Visible'} />
                      </button>
                    </li>
                  )
                })}
              </ul>
            </ScrollArea>
          </Section>
        </>
      ) : null}

      <Separator />
      <p className="px-4 py-3 text-[11px] leading-snug text-pretty text-muted-foreground">
        Layout is a 3-D view of 400-d vectors; rankings use true 400-d L2 distance over {fmt(scene.meta.universe)} compounds.
      </p>
    </aside>
  )
}
